  const loadChat=async(resource:Resource)=>{if(busy){setToast("Une réponse est encore en cours.");return;}try{setError("");const data=await api("/api/chat?conversationId="+resource.id);shouldFollowMessages.current=true;setShowLatest(false);setMessages(data.messages.map((m:any)=>({id:m.id,role:m.role,text:m.content.filter((b:any)=>b.type==="text").map((b:any)=>b.text).join("\n"),attachments:Array.isArray(m.attachments)?m.attachments:[]})));setConversationId(resource.id);navigate("chat");}catch(e:any){setError(e.message);}};
