  const cancelUpload=async(taskId:string)=>{const item=uploadProgress.find(progress=>progress.taskId===taskId);uploadControllers.current.get(taskId)?.abort();if(item?.uploadId&&item.phase!=="Validation du fichier")try{await api(`/api/files/uploads?uploadId=${encodeURIComponent(item.uploadId)}`,{method:"DELETE"});}catch{}setUploadProgress(current=>current.filter(progress=>progress.taskId!==taskId));void refreshPendingUploads();};
