 const importSkill=async(file?:File)=>{if(!file)return;if(authRequired){setModal("auth");return;}if(file.size>24*1024){setError("Le fichier de compétence doit faire moins de 24 Ko.");return;}setUploading(true);setError("");try{const content=await file.text();if(!content.trim())throw new Error("Ce fichier est vide.");const lines=content.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);const title=lines.find(line=>/^#\s+/.test(line))?.replace(/^#\s+/,"").trim()||file.name.replace(/\.(md|markdown|txt)$/i,"").replace(/[-_]+/g," ").trim();const section=(names:string[])=>{const pattern=new RegExp("^#{1,4}\\s*(?:"+names.join("|")+")\\b","i");const start=lines.findIndex(line=>pattern.test(line));if(start<0)return[];const out:string[]=[];for(const line of lines.slice(start+1)){if(/^#{1,4}\s/.test(line))break;const item=line.replace(/^(?:[-*+]\s+|\d+[.)]\s+)/,"").trim();if(item)out.push(item.slice(0,500));if(out.length===20)break;}return out;};const description=lines.find(line=>!/^#/.test(line)&&!/^[-*+]\s/.test(line)&&!(/^\d+[.)]\s/.test(line)))?.replace(/^(?:description|objectif)\s*:\s*/i,"").slice(0,1200)||"Méthode importée, conservée dans votre espace privé.";const steps=section(["étapes?","steps?","méthode","procedure","process"]);const checks=section(["vérifications?","checks?","validation","criteria","critères"]);const objective=section(["objectif","objective","purpose"])[0]||description;const slug=file.name.replace(/\.(md|markdown|txt)$/i,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,80)||"competence-importee";await api("/api/workspace",post({kind:"skill",title:title.slice(0,160),data:{slug,category:"operations",description,objective,steps,checks,tools:[],source:"Import utilisateur · "+file.name.slice(0,120),content:content.slice(0,24000)}}));await refresh();setToast("Compétence importée dans votre espace privé · à évaluer.");}catch(e:any){setError(e.message||"Impossible d’importer cette compétence.");}finally{setUploading(false);if(skillFileInput.current)skillFileInput.current.value="";}};
